/**
 * @file WorldGeneratedInteractiveObject.h
 * @author Bartosz Han
 * @brief This file contains WorldGeneratedInteractiveObject, which is used by another classes of objects,
 * which are used only as object on world map, and are generated by ObjectGenerator objects.
 *
 */

#ifndef WORLD_GENERATED_INTERACTIVE_OBJECT_H
#define WORLD_GENERATED_INTERACTIVE_OBJECT_H

#include "GameObjects/BaseObjects/InteractiveObject.h"
#include "Data/Constants.hpp"

/**
 * @class WorldGeneratedInteractiveObject
 * @brief This class is used in another classes of objects, which are objects related only to the world map
 * (theses objects should not exists outside the world map) and are only generated by the ObjectGenerator objects into the world map.
 *
 * @note Classes, which inherits from this class, should have default constructor, due to how ObjectGenerator generates theses objects.
 *
 */
class WorldGeneratedInteractiveObject : public InteractiveObject{

public:
    /**
     * @brief Construct a new WorldGeneratedInteractiveObject.
     *
     * @param initial_texture_name Path to texture of this object.
     * @param object_type Type of the object.
     * @param priority Integer representing priority of the object, when other object might attempt to interact with several objects at a time.
     * @param destroy_after_interaction Flag, informing whther or not this object should be destroyed after one interaction with other object.
     */
    WorldGeneratedInteractiveObject(const std::string initial_texture_name, const ObjectType object_type,
        const int priority = constants::OTHER_OBJECT_PRIORITY, const bool destroy_after_interaction = true);

    WorldGeneratedInteractiveObject(const ObjectType object_type,
        const int priority = constants::OTHER_OBJECT_PRIORITY, const bool destroy_after_interaction = true);

    /**
     * @brief Set values of the coordinates of this object into given coordinates.
     *
     * This method only changes the values of the variables of this object,
     * and this method does not affect the world map.
     *
     * This method is need due to how Objectgenerator generates objects. This method should only be used once per object.
     */
    void setPos(const std::pair<int, int> pos);
};

#endif

